INSERT INTO VIDEO_INTERVIEW (
	INTERVIEW_NO
	, ROOM_TITLE
	, MAX_JOIN_COUNT
	, START_DATE
	, END_DATE
	, COMPANY_INTERVIEW_URL
	, VIDEO_INTERVIEW_DEL_DATE
	, ROOM_ID
) VALUES (
	#{interviewNo}
	, #{roomTitle}
	, #{maxJoinCount}
	, TO_DATE(REPLACE(#{startDate}, 'T', ' '), 'YYYY-MM-DD HH24:MI')
	, TO_DATE(REPLACE(#{endDate}, 'T', ' '), 'YYYY-MM-DD HH24:MI')
	, #{companyInterviewUrl}
	, #{videoInterviewDelDate}
	, #{roomId}
)
